local p = {} --p stands for package

local getArgs = require('Module:Arguments').getArgs

function p._CSS_unit(args)
	return string.sub(string.gsub(args[1] or args.source or "", "^[%d.]+", ""), 1, -1)
end

function p.CSS_unit(frame)
	return p._CSS_unit(getArgs(frame))
end

return p

local function any_case(str)
	return str:gsub('.', function (chr)
		if chr:match('%a') then -- letters
			return '[' .. chr:lower() .. chr:upper() .. ']'
		else
			return chr -- leave as-is
		end
	end)
end
