require('strict')

local p = {}

local getArgs = require('Module:Arguments').getArgs
local yesno = require('Module:Yesno')

function p._namespace_other(args)
	local namespace = string.lower(args.demospace or mw.title.getCurrentTitle().nsText)
	namespace = string.gsub(namespace, ' ', '_')
	local target = string.lower(args.target or 'main')

	if yesno(args['include-talk']) then
		namespace = string.gsub(namespace, '[%s_]*talk', '')
	end

	local special_targets = {
		['talk'] = function (ns)
			return mw.title.new(mw.title.getCurrentTitle().rootText, ns).isTalkPage
		end,
		['main'] = function (ns)
			return ns == '' or ns == 'main'
		end
	}

	if namespace == target or (special_targets[target] and special_targets[target](namespace)) then
		return args[1]
	else
		return args[2]
	end
end

function p.namespace_other(frame)
	return p._namespace_other(getArgs(frame))
end

local function _page_index_other(args)
	local page_entry = args['page index'] or args['page'] or args[1]
	local index_entry = args['page index'] or args['index'] or args[2]
	local other_entry = args['other'] or args[3]

	local namespace = string.lower(args.demospace or mw.title.getCurrentTitle().nsText)
	namespace = string.gsub(namespace, ' ', '_')
	namespace = string.gsub(namespace, '[%s_]*talk', '')

	return (namespace == 'page' and page_entry) or (namespace == 'index' and index_entry) or other_entry
end

function p.page_index_other(frame)
	return _page_index_other(getArgs(frame))
end

return p

/**
 * Style for horizontal lists (separator following item).
 * @source mediawiki.org/wiki/Snippets/Horizontal_lists
 * @revision 7 (2015-11-12)
 * @author [[User:Edokter]]
 */
.wst-flatlist {
    display: inline-block;
}

.wst-flatlist dl,
.wst-flatlist ol,
.wst-flatlist ul {
    margin: 0;
    padding: 0;
}
/* Display list items inline */
.wst-flatlist dd,
.wst-flatlist dt,
.wst-flatlist li {
    display: inline;
    margin: 0;
}
/* Do not display empty list items */
.wst-flatlist li.mw-empty-li {
    display: none;
    margin: 0;
}
/* Display nested lists inline */
.wst-flatlist.inline,
.wst-flatlist.inline dl,
.wst-flatlist.inline ol,
.wst-flatlist.inline ul,
.wst-flatlist dl dl, .wst-flatlist dl ol, .wst-flatlist dl ul,
.wst-flatlist ol dl, .wst-flatlist ol ol, .wst-flatlist ol ul,
.wst-flatlist ul dl, .wst-flatlist ul ol, .wst-flatlist ul ul {
    display: inline;
}
/* Generate interpuncts */
.wst-flatlist dt:after {
    content: ": ";
}
.wst-flatlist dd:after,
.wst-flatlist li:after {
    content: " \00B7 ";
    font-weight: bold;
}

/* Comma separators */
.wst-flatlist-comma dd:after,
.wst-flatlist-comma li:after {
    content: ", ";
    font-weight: normal;
}

.wst-flatlist dd:last-child:after,
.wst-flatlist dt:last-child:after,
.wst-flatlist li:last-child:after {
    content: none;
}
/* Add parentheses around nested lists */
.wst-flatlist dd dd:first-child:before, .wst-flatlist dd dt:first-child:before, .wst-flatlist dd li:first-child:before,
.wst-flatlist dt dd:first-child:before, .wst-flatlist dt dt:first-child:before, .wst-flatlist dt li:first-child:before,
.wst-flatlist li dd:first-child:before, .wst-flatlist li dt:first-child:before, .wst-flatlist li li:first-child:before {
    content: " (";
    font-weight: normal;
}
.wst-flatlist dd dd:last-child:after, .wst-flatlist dd dt:last-child:after, .wst-flatlist dd li:last-child:after,
.wst-flatlist dt dd:last-child:after, .wst-flatlist dt dt:last-child:after, .wst-flatlist dt li:last-child:after,
.wst-flatlist li dd:last-child:after, .wst-flatlist li dt:last-child:after, .wst-flatlist li li:last-child:after {
    content: ") ";
    font-weight: normal;
}
/* Put ordinals in front of ordered list items */
.wst-flatlist ol {
    counter-reset: listitem;
}
.wst-flatlist ol > li {
    counter-increment: listitem;
}
.wst-flatlist ol > li:before {
    content: " " counter(listitem) " ";
    white-space: nowrap;
}
.wst-flatlist dd ol > li:first-child:before,
.wst-flatlist dt ol > li:first-child:before,
.wst-flatlist li ol > li:first-child:before {
    content: " (" counter(listitem) " ";
}

