/* Basic alignment */
.wst-center {
	text-align: center;
	margin:0 auto;
}

/*
 * p-wrapping gives us a hard 7px bottom margin that is undesireable when
 * trying to align another element just below us (like a horizontal rule).
 * This is a workaround for that by simply forcing the margin to zero.
 */
.wst-center.wst-center-nomargin > p {
	margin-top: 0;
	margin-bottom: 0;
}

/* main container: flex-box with wrapping, align to centre */
.wst-flex-wrap-center {
	margin: auto; /* centre in page if width < 100% */
	display: flex;
	flex-wrap: wrap;
    justify-content: center;
}

/* the direct childen have this class */
.wst-flex-wrap-center > ._flex_child {
	/* default: a little padding on each side to separate cells */
	/* can be overridden on a per-cell basis */
	margin: 0.5em;
}

/* utility class if you want to remove child padding (can override without this) */
.wst-flex-wrap-center > ._flex_child._no_margin {
	margin: 0;
}

.wst-flex-wrap-center img {
	max-width: 100%; /* don't allow the imge to overspill containers */
	height: auto; /* maintain aspect ratio */
}

.wst-uppercase {
	text-transform: uppercase;
}

.wst-size-block {
	line-height:1.4;
}

/* 
 * NOTE: Works around the mobile skin setting font size for p tags.
 *
 * Inside a size block, all p elements should inherit font size, in this case
 * from the containing div from one of our size templates. And since
 * TemplateStyles 1) are scoped with an extra .mw-parser-output class and
 * 2) loaded after (later) than the skin, we get the same specificity (0-2-1)
 * and win on a tie.
 */
.wst-size-block p {
	font-size: inherit;
}

.wst-xx-smaller {
	font-size:58%;
}
.wst-x-smaller {
	font-size:69%;
}
.wst-smaller {
	font-size:83%;
}
.wst-fine {
	line-height:1.4;
	font-size:92%;
}
.wst-m-larger {
	font-size:110%;
}
.wst-larger {
	font-size:120%;
}
.wst-x-larger {
	font-size:144%;
}
.wst-xx-larger {
	font-size:182%;
}
.wst-xxx-larger {
	font-size:207%;
}
.wst-xxxx-larger {
	font-size:249%;
}
